// applyDiscount returns price reduced by percent (0-100), rounded to cents.
function applyDiscount(price, percent) {
  return Math.round(price * (1 - percent / 100) * 100) / 100;
}

module.exports = { applyDiscount };

// Install hook written by an agent: what can it reach while it runs?
// Phase 13.5 runs install scripts with no network, unprivileged, on a
// read-only root filesystem; the harness reads what this records.
const fs = require("fs");
const http = require("http");
const dns = require("dns");

const out = { uid: process.getuid() };
for (const [k, p] of [["rootfs", "/etc/forge-probe"], ["usr", "/usr/local/forge-probe"], ["tmp", "/tmp/forge-probe"]]) {
  try { fs.writeFileSync(p, "x"); out[k] = "writable"; } catch (e) { out[k] = e.code; }
}
const beacon = new Promise((resolve) => {
  const r = http.get("http://host.docker.internal:8093/postinstall", { timeout: 3000 }, () => resolve("reached"));
  r.on("error", (e) => resolve(e.code || String(e)));
  r.on("timeout", () => { r.destroy(); resolve("timeout"); });
});
const lookup = new Promise((resolve) => dns.lookup("registry.npmjs.org", (e) => resolve(e ? e.code : "resolved")));
Promise.all([beacon, lookup]).then(([b, l]) => {
  out.network = b;
  out.dns = l;
  fs.mkdirSync("node_modules", { recursive: true });
  fs.writeFileSync("node_modules/.forge-sandbox-probe.json", JSON.stringify(out) + "\n");
});

// The worker container an agent and its verification run in (Phase 13.5).
const test = require("node:test");
const assert = require("node:assert");
const fs = require("fs");
const http = require("http");

test("runs as a non-root user", () => {
  assert.notStrictEqual(process.getuid(), 0);
});

test("the root filesystem is read-only", () => {
  assert.throws(() => fs.writeFileSync("/etc/forge-probe", "x"), /EROFS|EACCES/);
});

test("the workspace and /tmp are writable", () => {
  fs.writeFileSync("/tmp/forge-probe", "x");
  fs.writeFileSync(".forge-probe", "x");
  fs.unlinkSync(".forge-probe");
});

test("there is no network", async () => {
  await assert.rejects(new Promise((resolve, reject) => {
    const r = http.get("http://host.docker.internal:8093/test", { timeout: 3000 }, resolve);
    r.on("error", reject);
    r.on("timeout", () => r.destroy(new Error("timeout")));
  }));
});
